import gen from './breakpoints.gen.json';

/**
 * The only place media conditions are read (no hand-written media strings elsewhere in src/).
 * `breakpoints.gen.json` is generated by Lean (`pnpm gen:breakpoints`; the build byte-checks it). Ids are the
 * inventory ids (e.g. "mq.rm-reduce", "mq.c860").
 */
type Gen = { conditions: { id: string; tsId: string; css: string }[] };
const conditions = new Map((gen as Gen).conditions.map((c) => [c.id, c.css]));

export function mediaCondition(id: string): string {
  const c = conditions.get(id);
  if (c === undefined) throw new Error(`unknown breakpoint condition "${id}"`);
  return c;
}
